def refs(o):
 if isinstance(o,dict):
  for k,v in o.items():
   if k in ('sample_refs','evidence_paths'):
    for p in v:
     f=ROOT/p;assert not Path(p).is_absolute() and f.is_file() and f.stat().st_size>0,(k,p)
   else:refs(v)
 elif isinstance(o,list):
  for c in o:refs(c)
refs(v)
